#!/usr/bin/env python3
"""Validate the committed schema-1 PR #360 benchmark evidence."""

from __future__ import annotations

import hashlib
import json
import sys
from collections import Counter
from pathlib import Path


def main(path: str) -> None:
    report = json.loads(Path(path).read_text())
    assert report["schema_version"] == 1
    assert len(report["base_sha"]) == len(report["candidate_sha"]) == 40
    assert report["working_tree_clean_before_benchmark"] is True
    clean_state = report["pre_benchmark_clean_state"]
    assert clean_state["command"] == ["git", "status", "--porcelain", "--untracked-files=all"]
    assert clean_state["stdout"] == ""
    source = report["worker_source"]
    assert source == report["orchestrator_source"]
    assert hashlib.sha256(source.encode()).hexdigest() == report["script_sha256"]
    assert hashlib.sha256(Path("uv.lock").read_bytes()).hexdigest() == report["lock_sha256"]
    observations = report["observations"]
    parity = [row for row in observations if row["mode"] == "parity"]
    measured = [row for row in observations if row["mode"] == "measure"]
    assert len(parity) == 136
    assert len(measured) == 312

    regular = [row for row in parity if row["operation"] != "welch"]
    assert len(regular) == 13 * 4 * 2
    assert all(row["exact"] and row["whole_checksum"] == row["candidate_checksum"] for row in regular)
    assert {
        (row["operation"], row["channels"], row["input_dtype"]) for row in regular
    } == {
        (operation, channels, dtype)
        for operation in report["operations"]
        for channels in (1, 2, 4, 8)
        for dtype in ("float32", "float64")
    }

    welch = [row for row in parity if row["operation"] == "welch"]
    assert len(welch) == 4 * 4 * 2
    for row in welch:
        expected_exact = row["detrend"] == "constant" or row["channels"] == 1
        assert row["exact"] is expected_exact
        assert (row["whole_checksum"] == row["candidate_checksum"]) is expected_exact
        if not expected_exact:
            assert 0 < row["max_abs_difference"] < 1e-8

    counts = Counter(
        (row["operation"], row["channels"], row["boundary"], row["path"])
        for row in measured
    )
    expected = {
        (operation, channels, boundary, path)
        for operation in report["operations"]
        for channels in (4, 8)
        for boundary in ("operation", "frame_data")
        for path in ("whole", "candidate")
    }
    assert set(counts) == expected
    assert set(counts.values()) == {3}
    for key in expected:
        rows = [
            row for row in measured
            if (row["operation"], row["channels"], row["boundary"], row["path"]) == key
        ]
        assert sorted(row["run_index"] for row in rows) == [1, 2, 3]
        assert len({row["checksum"] for row in rows}) == 1
        assert len({(tuple(row["output_shape"]), row["output_dtype"]) for row in rows}) == 1
        assert all(row["tasks"] > 0 and row["input_bytes"] > 0 and row["output_bytes"] > 0 for row in rows)
    paired_keys = {
        (row["operation"], row["channels"], row["boundary"])
        for row in measured
    }
    for operation, channels, boundary in paired_keys:
        whole_checksums = {
            row["checksum"] for row in measured
            if row["operation"] == operation
            and row["channels"] == channels
            and row["boundary"] == boundary
            and row["path"] == "whole"
        }
        candidate_checksums = {
            row["checksum"] for row in measured
            if row["operation"] == operation
            and row["channels"] == channels
            and row["boundary"] == boundary
            and row["path"] == "candidate"
        }
        assert whole_checksums == candidate_checksums
    print(
        json.dumps(
            {
                "status": "valid",
                "parity_cases": len(parity),
                "measurement_cases": len(measured),
                "three_rerun_groups": len(expected),
            }
        )
    )


if __name__ == "__main__":
    main(sys.argv[1])
